-- ============================================
-- Gift Results Table (선물 결과 링크 영속화)
-- ============================================
-- Migration: 009_add_gift_results
-- Created: 2026-08-01
--
-- Stores the shareable result generated by /api/gift/send so that the
-- emailed `/result/{token}` link keeps working until it expires.

CREATE TABLE IF NOT EXISTS gift_results (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  token TEXT UNIQUE NOT NULL,
  sender_name TEXT,
  recipient_email TEXT,
  message TEXT,
  payload JSONB,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ,
  opened_at TIMESTAMPTZ
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_gift_results_token ON gift_results(token);
CREATE INDEX IF NOT EXISTS idx_gift_results_expires_at ON gift_results(expires_at);

-- ============================================
-- RLS
-- ============================================
-- Token-based lookups are served exclusively by service-role API routes
-- (/api/gift/[token]); recipients are anonymous, so NO anon/authenticated
-- policies are created. Enabling RLS with no policies blocks all
-- non-service-role access by default.
ALTER TABLE gift_results ENABLE ROW LEVEL SECURITY;
